from fractions import Fraction
from typing import List

def v2_den(q: Fraction) -> int:
    b, k = q.denominator, 0
    while b % 2 == 0:
        b //= 2; k += 1
    return k

def escapee(S: List[Fraction]) -> Fraction:
    """A dyadic number outside the subgroup generated by S."""
    N = max((v2_den(s) for s in S), default=0)
    return Fraction(1, 2 ** (N + 1))
